const accessibleRow=mid=>scopedRows().find(r=>r['公司 MID']===mid);
const cellValue=(r,h)=>h==='商戶狀態'?statusNames[r.status]:String(r[h]??'');
filteredRows=function(){const q=state.search.trim().toLowerCase();let list=scopedRows().filter(r=>(state.status==='全部狀態'||statusNames[r.status]===state.status)&&(!q||(state.searchScope==='全部欄位'?headers.map(h=>cellValue(r,h)).join(' '):cellValue(r,state.searchScope)).toLowerCase().includes(q))&&Object.entries(DEMO.columnFilters).every(([h,vals])=>vals.includes(cellValue(r,h))));if(BO.sort)list.sort((a,b)=>cellValue(a,BO.sort).localeCompare(cellValue(b,BO.sort),'zh-Hant',{numeric:true})*(BO.desc?-1:1));return list;};
const pageButtons=(page,count,action='page')=>{const max=Math.max(1,count);return `<div class="pagination">${btn('‹',action,'',`aria-label="上一頁" data-page="${page-1}" ${page<=1?'disabled':''}`)}${[...new Set([1,Math.max(1,page-1),page,Math.min(max,page+1),max])].sort((a,b)=>a-b).map(n=>btn(n,action,n===page?'primary':'',`data-page="${n}"`)).join('')}${btn('›',action,'',`aria-label="下一頁" data-page="${page+1}" ${page>=max?'disabled':''}`)}</div>`};
function heading(title,description=''){return `<div class="page-heading"><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>`;}
dashboard=function(){const list=scopedRows().filter(r=>DEMO.period==='30'||r.createdDay>=24),counts=['all','Pending','MoreInfo','SyncFailed'].map(s=>s==='all'?list.length:list.filter(r=>r.status===s).length);return `${heading('儀表板','營運總覽 · 優先處理風險、待辦及重點商戶。')}${demoBar()}<div class="toolbar"><select aria-label="統計日期範圍" id="demo-period"><option value="30">最近 30 天</option><option value="7" ${DEMO.period==='7'?'selected':''}>最近 7 天</option></select><span class="grow hint">資料範圍：${BO.user.role.includes('代理')?'所屬代理商':'全部商戶'} · 即時 Demo 數據</span>${can(1)?btn('新增商戶','new','primary'):''}</div><div class="metrics">${['商戶總數','待審核','待補資料','同步失敗'].map((name,i)=>`<button class="metric" data-action="metric" data-index="${i}"><span>${name}</span><strong>${counts[i]}</strong><small>${['查看全部商戶 →','查看審核清單 →','查看補件清單 →','核對失敗原因 →'][i]}</small></button>`).join('')}</div><section class="card"><h2>優先待辦 <span class="muted">Priority Actions</span></h2><p class="hint">依處理急迫程度排序，點擊「處理」開啟商戶審核。</p>${[['緊急','同步失敗',counts[3]+' 間商戶等待重新同步，請確認銀行資料與驗證結果。'],['即將到期','證照提醒',list.filter(r=>r['BR 有效期']==='2026/10/05').length+' 間商戶的 BR 將於 30 日內到期。'],['待跟進','審核與補件',counts[1]+' 間待審核；'+counts[2]+' 間待補資料。'],['可續填','尚未提交草稿',scopedDrafts().length+' 份草稿尚未完成，可從草稿頁繼續填寫。']].map(([tag,title,copy])=>`<div class="priority-row"><span class="priority-label">${tag}</span><strong>${title}</strong><p>${copy}</p>${btn('處理','priority-review')}</div>`).join('')}</section><section class="card"><h2>VIP／重點商戶 <span class="muted">Key Accounts</span></h2><p class="hint">需要優先跟進的商戶與目前進度。</p>${list.filter(r=>r.vip).slice(0,4).map(r=>`<div class="priority-row"><strong>${esc(r['客戶中文名稱'])}</strong><span>負責人：${esc(r['主代理商'])}</span>${pill(statusNames[r.status],statusColors[r.status])}${btn('查看商戶','detail','',`data-mid="${r['公司 MID']}"`)}</div>`).join('')||'<p class="hint">本區間沒有重點商戶。</p>'}</section><section class="card"><h2>最新動態 <span class="muted">Recent Activity</span></h2>${visibleAudit().slice(0,5).map(a=>`<p class="hint">${esc(a.time)}　${esc(a.user)} · ${esc(a.message)}</p>`).join('')}${can(11)?btn('查看全部記錄','activity'):''}</section>`;};
function visibleAudit(){return BO.user?.role.includes('代理')?BO.audit.filter(a=>a.user===BO.user.name):BO.audit;}
merchantCell=function(r,h){const id=esc(r['公司 MID']);if(h==='操作')return `<td><div class="row-actions">${can(2)?btn('編輯','edit','',`data-mid="${id}"`):''}${btn('公司詳情','detail','',`data-mid="${id}"`)}${can(6)?btn('BR轉換','transfer','',`data-mid="${id}"`):''}${can(7)?btn('審核','review-merchant','review-button',`data-mid="${id}" ${!['Pending','MoreInfo'].includes(r.status)?'disabled':''}`):''}${can(8)?btn('同步至 All-In Pay','sync','sync-button',`data-mid="${id}" ${!['Approved','SyncFailed'].includes(r.status)?'disabled':''}`):''}</div></td>`;if(h==='銀行帳號'&&!can(5))return `<td>${esc(r[h])}</td>`;return originalCell(r,h);};
merchants=function(){let list=filteredRows(),pages=Math.max(1,Math.ceil(list.length/DEMO.size));state.page=Math.min(Math.max(1,state.page),pages);const shown=list.slice((state.page-1)*DEMO.size,state.page*DEMO.size),cols=[...BO.pins,...BO.order.filter(h=>!BO.pins.includes(h))].filter(h=>!BO.hidden.has(h)),widths=cols.map(h=>h==='操作'?580:h==='選取'?64:/中文名稱|英文名稱/.test(h)?240:180);const style=(h,i)=>`${BO.pins.includes(h)?'class="pinned" ':''}style="width:${widths[i]}px;${BO.pins.includes(h)?'left:'+widths.slice(0,i).reduce((s,v)=>s+v,0)+'px;':''}"`;return `${heading('商戶管理','公司 MID／BR 管理（Excel 表單）')}${demoBar()}${state.noticeCount?`<div class="notice toolbar"><span class="grow">${state.noticeCount} 筆新加入或修改的商戶資料待確認</span>${btn('確認已讀','read-notice')}</div>`:''}<section class="card"><div class="search-grid"><div><label for="merchant-search">跨欄位搜尋</label><input id="merchant-search" value="${esc(state.search)}" placeholder="搜尋公司名稱、MID、BR、代理商或聯絡人"></div><div><label for="search-scope">搜尋範圍</label><select id="search-scope">${['全部欄位',...headers.filter(h=>!['選取','操作'].includes(h))].map(h=>`<option ${state.searchScope===h?'selected':''}>${esc(h)}</option>`).join('')}</select></div><div><label for="merchant-status">商戶狀態</label><select id="merchant-status">${['全部狀態',...Object.values(statusNames)].map(h=>`<option ${state.status===h?'selected':''}>${h}</option>`).join('')}</select></div>${btn('重設','reset-search')}${btn('搜尋','search','primary')}</div></section><div class="toolbar"><label class="check"><input type="checkbox" id="demo-select-page" ${shown.length&&shown.every(r=>state.selected.has(r['公司 MID']))?'checked':''}>全選本頁</label><span id="selected-count">已選 ${state.selected.size} 家</span><span class="grow"></span>${btn('顯示／排列欄位','columns')}${can(4)?btn('匯出 CSV','export-merchants'):''}${can(8)?btn('批次同步','batch-sync','sync-button'):''}</div>${Object.keys(DEMO.columnFilters).length?`<div class="filter-tags">${Object.entries(DEMO.columnFilters).map(([h,v])=>btn(esc(h)+'：'+v.length+' 項 ×','remove-column-filter','',`data-col="${esc(h)}"`)).join('')}</div>`:''}<div class="table-wrap"><table class="merchants merchant-table-new" style="width:${widths.reduce((s,v)=>s+v,0)}px"><thead><tr>${cols.map((h,i)=>`<th scope="col" ${style(h,i)}><span class="merchant-head">${esc(h)}${!['選取','操作'].includes(h)?btn((BO.sort===h?(BO.desc?'↓ ':'↑ '):'')+'▾','column-menu',DEMO.columnFilters[h]?'filtered':'',`data-col="${esc(h)}" aria-label="${esc(h)}欄位選單" aria-haspopup="dialog"`):''}</span></th>`).join('')}</tr></thead><tbody>${shown.map(r=>`<tr>${cols.map((h,i)=>merchantCell(r,h).replace('<td>',`<td ${style(h,i)}>`)).join('')}</tr>`).join('')||`<tr><td colspan="${cols.length}">沒有符合條件的商戶，請調整篩選。</td></tr>`}</tbody></table></div><div class="table-footer"><span class="hint">顯示 ${list.length?(state.page-1)*DEMO.size+1:0}–${Math.min(state.page*DEMO.size,list.length)}，共 ${list.length} 筆 · 全部為假資料</span><label>每頁 <select id="demo-page-size">${[20,40,80].map(n=>`<option ${n===DEMO.size?'selected':''}>${n}</option>`).join('')}</select> 筆</label>${pageButtons(state.page,pages)}</div>`;};
function closeColumn(){const menu=$('#column-popover');if(menu)menu.remove();DEMO.menu=null;}
function showColumn(el){closeColumn();const h=el.dataset.col,values=[...new Set(scopedRows().map(r=>cellValue(r,h)))].sort((a,b)=>a.localeCompare(b,'zh-Hant',{numeric:true}));DEMO.menu={h,values,selected:new Set(DEMO.columnFilters[h]||values),query:'',choice:BO.sort===h?(BO.desc?'desc':'asc'):null,anchor:el};const p=document.createElement('section');p.id='column-popover';p.className='column-popover';p.setAttribute('role','dialog');p.setAttribute('aria-label',h+'欄位選單');const rect=el.getBoundingClientRect();p.style.left=Math.max(8,Math.min(innerWidth-268,rect.right-260))+'px';p.style.top=Math.max(8,Math.min(innerHeight-390,rect.bottom+6))+'px';p.innerHTML=`<strong>${esc(h)}</strong><div class="column-choices">${[['asc','升序排列'],['desc','降序排列'],['hide','隱藏此欄']].map(([v,l])=>btn(l,'column-choice',DEMO.menu.choice===v?'active':'',`data-choice="${v}" aria-pressed="${DEMO.menu.choice===v}"`)).join('')}</div><div class="menu-rule"></div><input id="column-search" aria-label="搜尋此欄位內容" placeholder="搜尋此欄位內容" autocomplete="off"><div id="column-results"><p class="hint">輸入關鍵字後顯示符合的內容</p></div><footer>${btn('清除','column-clear')}${btn('套用','column-apply','primary')}</footer>`;document.body.append(p);$('#column-search').focus();}
function columnResults(){const m=DEMO.menu;if(!m)return;const list=m.values.filter(v=>v.toLowerCase().includes(m.query.toLowerCase()));$('#column-results').innerHTML=!m.query.trim()?'<p class="hint">輸入關鍵字後顯示符合的內容</p>':`<div class="column-bulk">${btn('全選','column-all','text-button')}${btn('取消全選','column-none','text-button')}<small>${m.selected.size} 已選</small></div><div class="column-list">${list.map(v=>`<label><input type="checkbox" data-column-value="${esc(v)}" ${m.selected.has(v)?'checked':''}><span>${esc(v||'（空白）')}</span></label>`).join('')||'<p class="hint">沒有相符內容</p>'}</div>`;}
const uiToOld={1:5,2:1,3:2,4:3,5:4,6:6},oldToUi={1:2,2:3,3:4,4:5,5:1,6:6};
steps.splice(0,steps.length,'文件材料','主體資料','經營與聯繫','結算帳戶','產品與費率','確認提交');
const legacyApplication=application,legacyValidate=validateStep,legacyReview=review,legacyUpload=uploadRow,legacyFill=fillSample;
validateStep=step=>legacyValidate(uiToOld[step]);
review=()=>legacyReview().replace(/data-step="([1-6])"/g,(_,n)=>`data-step="${oldToUi[n]}"`).replaceAll('Step 5','Step 1');
const friendlyProducts=['線下收單 · In-store Acquiring','線上外卡 · Online Card Payments','線下掃碼 · In-store QR Payments','線上掃碼 · Online QR Payments','帳戶驗證 · Account Verification','一碼付 · Unified QR Payments','支付連結 · Payment Links'];
forms[3].sections.slice(0,7).forEach((s,i)=>{s.texts[0]=friendlyProducts[i];s.texts[1]='勾選需要開通的產品，可同時選擇多項。';});
forms[4].sections[0].texts[1]='依法律主體、產品及風險決定必交項目。PDF／JPG／PNG／ZIP，每檔上限 10 MB；文件僅留在目前瀏覽器。';
application=function(step){let html=legacyApplication(uiToOld[step]);if(step===1)html=`<section class="br-callout"><div><h2>先匯入 BR，讓系統幫你填</h2><p>核對辨識結果後，帶入主體資料與經營資料。</p><small>本 HTML 使用固定假資料演示；實際文件辨識請使用獨立 BR 工具。</small></div><div>${btn('匯入 BR','br-start','primary')}<a href="https://notdesign.github.io/allinpay-br-demo/" target="_blank" rel="noopener noreferrer">開啟本機 BR 辨識工具 ↗</a></div></section>`+html;return html;};
function invitationSource(){
  if(!can(1))return null;
  const user=BO.user,isAgent=user.role.includes('代理'),code=isAgent?user.agencyCode:user.id;
  if(!code)return null;
  const label=isAgent?'代理商代碼':'邀請帳號',query=isAgent?'agency':'inviter';
  return {label,code,isAgent,identity:`${user.role}：${user.name} · ${label}：${code}`,link:'https://notdesign.github.io/allinpay-merchant-demo/external.html?'+query+'='+encodeURIComponent(code)};
}
function invitation(){const source=invitationSource();return source?`<section class="agency-invitation"><div><h3>邀請客戶填寫</h3><p>分享你的專屬申請連結，客戶可自行填寫；連結會附上你的${source.label}。</p><small>${esc(source.identity)}</small></div>${btn('分享我的申請連結','share-agency','primary')}</section>`:'';}
uploadRow=function(u){const f=state.files[u.id],error=state.errors['file-'+u.id];return `<div class="upload-row ${error?'invalid':''}" data-upload-row="${u.id}"><div class="upload-heading"><div class="upload-name">${labelHTML(u.name)}${requiredFiles().includes(u.id)?' <span class="required">*</span>':''}</div>${f?pill('已選取','green'):pill('未選取')}</div><p class="hint">${esc(u.hint)}</p><div class="file-state ${f?'ready':''}">${f?esc(f.name)+(f.demo?' · 示例附件':f.needsReselect?' · 請重新選取':' · 僅本機'):'尚未選擇文件'}</div>${error?`<p class="error">${esc(error)}</p>`:''}<div class="upload-actions">${f?btn('預覽','preview-demo-file','',`data-id="${u.id}"`)+btn('移除','remove-file','danger',`data-id="${u.id}"`):''}${btn(f?'重新選擇':'選擇文件','demo-upload','',`data-id="${u.id}"`)}<input hidden type="file" data-demo-upload="${u.id}" accept=".pdf,.jpg,.jpeg,.png,.zip"></div></div>`;};
fillSample=function(row=rows[0]){legacyFill(row);state.values.registerCertNo=String(row.BR).replace(/^BR /,'').replace(/-\d{3}$/,'')+'-000';state.values.cardBankCode=row['銀行代碼']+' '+row['銀行名稱'];state.values.cardBankName=row['銀行名稱'];state.values.cardBranchCode=row['分行代碼'];state.values.developer=BO.user?.agencyCode||'MA-001';};
function draftSnapshot(id=state.draftId||'DRAFT-'+Date.now()){return {id,owner:BO.user.id,step:route().step,savedAt:new Date().toLocaleString('zh-HK',{hour12:false}),values:structuredClone(state.values),checks:structuredClone(state.checks),files:structuredClone(state.files),people:{...state.people},emailVerified:state.emailVerified};}
saveDraft=function(){if(!can(1))return deny();if(state.fail){modal('草稿儲存失敗','<div class="notice error">未能儲存，輸入內容仍保留在目前表單。</div><p>關閉「模擬失敗」後可重新儲存。</p>',btn('返回編輯','close')+btn('重試','save-draft','primary'));return;}const d=draftSnapshot(),before=state.drafts;state.drafts=[d,...state.drafts.filter(x=>x.id!==d.id)];if(!persistDemo()){state.drafts=before;return modal('草稿儲存失敗','<p>瀏覽器儲存空間不可用；請勿關閉此頁。</p>');}state.draftId=d.id;state.savedAt=d.savedAt;audit('儲存商戶草稿 · '+(d.values.merchantName||'未命名商戶'));persistDemo();modal('草稿儲存成功',`<div class="notice">${esc(d.values.merchantName||'未命名商戶')} 已儲存。</div><p>可從「已儲存的草稿」繼續填寫。實際附件只保留檔名，下次須重新選取。</p>`,btn('查看草稿','drafts')+btn('繼續填寫','close','primary'));};
draftView=function(){const ds=scopedDrafts(),pages=Math.max(1,Math.ceil(ds.length/20));DEMO.draftPage=Math.min(DEMO.draftPage,pages);return `${heading('已儲存的草稿','資料只存在目前瀏覽器，可繼續填寫或刪除。')}${demoBar()}<section class="card"><div class="table-scroll"><table class="accounts-table"><thead><tr><th>商戶／草稿編號</th><th>填寫進度</th><th>最後儲存</th><th>草稿狀態</th><th>操作</th></tr></thead><tbody>${ds.slice((DEMO.draftPage-1)*20,DEMO.draftPage*20).map(d=>`<tr><td>${esc(d.values.merchantName||'未命名商戶')}<small>${esc(d.id)}</small></td><td>Step ${d.step}／6 · ${steps[d.step-1]}</td><td>${esc(d.savedAt)}</td><td class="center">${pill(d.step>=5?'接近完成':'填寫中',d.step>=5?'blue':'')}</td><td><div class="row-actions">${btn('繼續填寫','restore','primary',`data-id="${d.id}"`)}${btn('刪除','delete-draft','danger',`data-id="${d.id}"`)}</div></td></tr>`).join('')||'<tr><td colspan="5">沒有草稿。請從新增商戶開始。</td></tr>'}</tbody></table></div><div class="table-footer"><span>共 ${ds.length} 份草稿</span>${pageButtons(DEMO.draftPage,pages,'draft-page')}</div></section>`;};
function queueModal(status){DEMO.queue=status;const list=scopedRows().filter(r=>r.status===status&&(DEMO.period==='30'||r.createdDay>=24));const p=Math.max(1,Math.min(DEMO.queuePage,Math.ceil(list.length/10)||1));DEMO.queuePage=p;modal(statusNames[status]+'商戶',`<p class="hint">共 ${list.length} 間 · 點擊右側操作查看或處理。</p><div class="table-scroll"><table class="accounts-table queue-table"><thead><tr><th>商戶／公司 MID</th><th>${status==='MoreInfo'?'待補項目':status==='SyncFailed'?'失敗原因':'申請狀態'}</th><th>操作</th></tr></thead><tbody>${list.slice((p-1)*10,p*10).map(r=>`<tr><td>${esc(r['客戶中文名稱'])}<small>${r['公司 MID']}</small></td><td>${status==='MoreInfo'?esc(r.missing.join('、')):status==='SyncFailed'?esc(r.syncReason):pill('待審核','amber')}</td><td>${btn(status==='Pending'?'審核':'查看詳情',status==='Pending'?'review-merchant':status==='MoreInfo'?'missing-detail':'sync-detail',status==='Pending'?'review-button':'',`data-mid="${r['公司 MID']}"`)}</td></tr>`).join('')||'<tr><td colspan="3">目前沒有待處理商戶。</td></tr>'}</tbody></table></div>${pageButtons(p,Math.ceil(list.length/10),'queue-page')}`,btn('關閉','close'));}
const reviewReasons={Rejected:['註冊資料與證明文件不一致','不符合收單服務範圍','證照無效或已到期','未符合風險審核要求','其他'],MoreInfo:['缺少銀行月結單','身份或地址證明不完整','BR 圖片不清晰','商戶聯絡資料待確認','其他']};
function reviewModal(mid,decision='Approved'){if(!can(7))return deny();const r=accessibleRow(mid);if(!r)return deny();if(!['Pending','MoreInfo'].includes(r.status))return modal('目前不可審核',`<p>${esc(r['客戶中文名稱'])} 目前狀態為「${statusNames[r.status]}」。</p>`);const previous=DEMO.review;DEMO.review={mid,decision,reason:previous?.mid===mid&&previous.decision===decision?previous.reason:'',note:previous?.mid===mid?previous.note:''};const rev=DEMO.review;modal('商戶審核',`<div class="profile-summary"><h3>${esc(r['客戶中文名稱'])}</h3><p>${esc(r['客戶英文名稱'])}</p><small>公司 MID：${mid} · 目前狀態：${statusNames[r.status]}</small></div><div class="review-decisions">${[['Approved','通過'],['Rejected','拒絕'],['MoreInfo','退回補件']].map(([v,l])=>`<label class="${v===decision?'active':''}"><input type="radio" name="review-decision" value="${v}" ${v===decision?'checked':''}>${l}</label>`).join('')}</div>${decision!=='Approved'?`<div class="field"><label for="review-reason">${decision==='Rejected'?'拒絕':'補件'}原因 <span class="required">*</span></label><select id="review-reason"><option value="">請選擇原因</option>${reviewReasons[decision].map(x=>`<option ${x===rev.reason?'selected':''}>${x}</option>`).join('')}</select></div>`:''}<div class="field"><label for="review-note">${decision==='Approved'?'審核備註（選填）':'補充說明 <span class="required">*</span>'}</label><textarea id="review-note" rows="3" maxlength="500" placeholder="請填寫具體原因，方便後續跟進">${esc(rev.note)}</textarea></div><p id="review-error" class="modal-error" role="alert"></p><p class="hint">此操作只更新 Demo 商戶狀態，不會通知真實商戶。</p>`,btn('取消','close')+btn('確認審核結果','review-confirm','review-button'));}
function persistMerchantChange(message){state.noticeCount++;audit(message);persistDemo();render();}
sync=function(mids){if(!can(8))return deny();const selected=mids.map(accessibleRow).filter(Boolean),eligible=selected.filter(r=>['Approved','SyncFailed'].includes(r.status));if(!eligible.length)return modal('沒有可同步的商戶','<p>只有「通過審核」或「同步失敗」的商戶可以同步。</p>');if(state.fail){eligible.forEach(r=>{r.status='SyncFailed';r.syncReason='模擬連線中斷，請稍後重試';});persistMerchantChange('模擬同步失敗 · '+eligible.length+' 間');return modal('同步失敗','<div class="notice error">未能完成同步，資料已保留，可從同步失敗清單重試。</div>');}eligible.forEach(r=>r.status='Synced');persistMerchantChange('完成模擬同步 · '+eligible.length+' 間');modal('同步完成',`<div class="notice">${eligible.length} 間商戶已模擬同步。</div>${eligible.length<selected.length?`<p>${selected.length-eligible.length} 間狀態不適用，已略過。</p>`:''}<p class="hint">沒有向 All-In Pay 發送任何資料。</p>`);};
